// Une la memoria leída de Airtable con el resultado del Worker (M2) y el canal de entrada (M4)
const ctxNode = $('Set Contexto Recurrente').isExecuted ? 'Set Contexto Recurrente' : 'Set Contexto Nuevo';
const ctx = $(ctxNode).first().json;
const log = $input.first().json;
const ent = $('Normalizar entrada').first().json;
const res = typeof log.resultado === 'string' ? log.resultado : JSON.stringify(log.resultado ?? '');
const nombreMemoria = ctx.user_name && ctx.user_name !== 'no informado' ? ctx.user_name : '';
return [{ json: {
  canal: ent.canal,
  user_name: nombreMemoria || ent.from_name || 'no informado',
  last_summary: ctx.last_summary || 'Sin historial previo',
  estado: ctx.estado || 'Nuevo',
  record_id: ctx.record_id,
  ruta: log.ruta || 'ESCALAR_HUMANO',
  resultado_worker: res.slice(0, 1500),
  chatInput: ent.chatInput
} }];

// Cuenta los mensajes del usuario y arma el historial para el modelo económico
let msgs = [];
for (const it of $input.all()) {
  const j = it.json;
  if (Array.isArray(j.messages)) msgs = msgs.concat(j.messages);
  else msgs.push(j);
}
const lineas = [];
let total_mensajes = 0;
for (const m of msgs) {
  const txt = (v) => typeof v === 'string' ? v : JSON.stringify(v);
  if (m.human !== undefined || m.ai !== undefined) {           // formato simplificado {human, ai}
    if (m.human !== undefined) { total_mensajes++; lineas.push('USUARIO: ' + txt(m.human)); }
    if (m.ai !== undefined) lineas.push('AGENTE: ' + txt(m.ai));
  } else {                                                      // formato LangChain {type, data:{content}}
    const esHumano = m.type === 'human' || m.role === 'user' || (m.id || []).includes('HumanMessage');
    const contenido = m.content ?? m.text ?? m.data?.content ?? m.kwargs?.content ?? '';
    if (esHumano) total_mensajes++;
    lineas.push((esHumano ? 'USUARIO: ' : 'AGENTE: ') + txt(contenido));
  }
}
const ctx = $('Preparar contexto del agente').first().json;
return [{ json: { total_mensajes, historial: lineas.join('\n'), record_id: ctx.record_id,
  last_summary: ctx.last_summary === 'Sin historial previo' || ctx.last_summary === 'Sin resumen previo' ? '' : ctx.last_summary } }];

// Parsea el JSON del modelo económico y lo deja listo para guardar (idempotente)
const crudo = ($input.first().json.text || '').trim();
const m = crudo.match(/\{[\s\S]*\}/);           // tolera texto extra alrededor del JSON
let r;
try { r = JSON.parse(m ? m[0] : crudo); }
catch (e) { r = { asunto_principal: 'Resumen no disponible', puntos_clave: [], accion_requerida: 'Revisión manual' }; }
const puntos = Array.isArray(r.puntos_clave) ? r.puntos_clave : [];
const pn = puntos.find(p => /^nombre\s*:/i.test(p));
const nombre = pn ? pn.split(':').slice(1).join(':').trim() : undefined;
const ctx = $('Contar mensajes').first().json;
return [{ json: {
  record_id: ctx.record_id,
  resumen: JSON.stringify(r),
  datos_clave: JSON.stringify({ nombre, puntos_clave: puntos, accion_requerida: r.accion_requerida, total_mensajes: ctx.total_mensajes }),
  estado: r.accion_requerida && r.accion_requerida !== 'ninguna' ? 'En seguimiento' : 'Abierto',
  fecha: new Date().toISOString()
} }];

// Unifica las dos puertas de entrada (chat y email) en un mismo contrato de datos
const j = $input.first().json;

// Canal CHAT: se mantiene el comportamiento del M3
if (j.chatInput !== undefined) {
  return [{ json: { canal: 'chat', sessionId: j.sessionId, chatInput: j.chatInput,
    from_email: '', from_name: '', subject: '', message_id: '', thread_id: '' } }];
}

// Canal EMAIL: se extrae solo lo mínimo viable (sin HTML, adjuntos ni headers)
let email = '', name = '';
if (j.from && j.from.value && j.from.value[0]) {
  email = j.from.value[0].address || '';
  name = j.from.value[0].name || '';
} else if (typeof j.From === 'string') {
  const m = j.From.match(/^\s*"?([^"<]*)"?\s*<([^>]+)>/);
  if (m) { name = m[1].trim(); email = m[2]; } else { email = j.From; }
}
email = email.toLowerCase().trim();
const subject = String(j.subject ?? j.Subject ?? '(sin asunto)').trim();
let body = String(j.text ?? j.textPlain ?? j.snippet ?? '');
body = body.replace(/\r/g, '')
  .split(/\nEl .{5,160} escribió:|\nOn .{5,160} wrote:/)[0]   // corta el hilo citado
  .replace(/\n{3,}/g, '\n\n')
  .slice(0, 3000).trim();

return [{ json: {
  canal: 'email',
  sessionId: email || ('email-sin-remitente-' + $execution.id),   // Session_ID = email del remitente
  chatInput: 'Asunto: ' + subject + '\n\n' + body,
  from_email: email, from_name: name, subject,
  message_id: j.id || '', thread_id: j.threadId || ''
} }];
